#include <iostream>
using namespace std;
int main() {
    int A[3][2], B[2][3], C[3][3];
    cout << "Enter elements of matrix A (3x2):" << endl;
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 2; j++) cin >> A[i][j];
    cout << "Enter elements of matrix B (2x3):" << endl;
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 3; j++) cin >> B[i][j];
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++) {
            C[i][j] = 0;
            for (int k = 0; k < 2; k++)
                C[i][j] += A[i][k] * B[k][j];
        }
    cout << "Product A x B (3x3):" << endl;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) cout << C[i][j] << "\t";
        cout << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;
int main() {
    int A[3][3], B[3][3], S[3][3], D[3][3];
    cout << "Enter matrix A (3x3):" << endl;
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++) cin >> A[i][j];
    cout << "Enter matrix B (3x3):" << endl;
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++) cin >> B[i][j];
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++) {
            S[i][j] = A[i][j] + B[i][j];
            D[i][j] = A[i][j] - B[i][j];
        }
    cout << "A + B:" << endl;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) cout << S[i][j] << "\t";
        cout << endl;
    }
    cout << "A - B:" << endl;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) cout << D[i][j] << "\t";
        cout << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;
int main() {
    int A[3][3], T[3][3];
    cout << "Enter matrix A (3x3):" << endl;
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++) cin >> A[i][j];
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            T[j][i] = A[i][j];
    cout << "Transpose of A:" << endl;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) cout << T[i][j] << "\t";
        cout << endl;
    }
    return 0;
}

