#include <iostream>
using namespace std;
int main() {
    char a[10], t;
    cout << "Enter ten alphabets: ";
    for (int i = 0; i < 10; i++) cin >> a[i];
    for (int i = 0; i < 9; i++)
        for (int j = i + 1; j < 10; j++)
            if (a[i] < a[j]) { t = a[i]; a[i] = a[j]; a[j] = t; }
    cout << "In descending order: ";
    for (int i = 0; i < 10; i++) cout << a[i] << " ";
    cout << endl;
    return 0;
}

